import os
import gzip

def generate_header():
    current_dir = os.path.dirname(os.path.abspath(__file__))
    web_dir = os.path.join(current_dir, 'web')
    output_header = os.path.join(current_dir, 'web_assets.h')

    files = [
        ('index.html', 'index_html_gz'),
        ('style.css', 'style_css_gz'),
        ('phf-view.js', 'phf_view_js_gz'),
        ('phf.js', 'phf_js_gz'),
        ('phf.wasm', 'phf_wasm_gz'),
        ('stream-client.js', 'stream_client_js_gz')
    ]

    lines = [
        "// Auto-generated by build_web_assets.py - DO NOT EDIT MANUALLY",
        "#ifndef WEB_ASSETS_H",
        "#define WEB_ASSETS_H",
        "",
        "#include <pgmspace.h>",
        "#include <stddef.h>",
        "#include <stdint.h>",
        ""
    ]

    total_raw = 0
    total_gz = 0

    for filename, var_name in files:
        filepath = os.path.join(web_dir, filename)
        if not os.path.exists(filepath):
            raise FileNotFoundError(f"Missing web asset: {filepath}")

        with open(filepath, 'rb') as f:
            raw_data = f.read()

        gz_data = gzip.compress(raw_data, compresslevel=9)
        total_raw += len(raw_data)
        total_gz += len(gz_data)

        print(f"Compressed {filename:16}: {len(raw_data):6} bytes -> {len(gz_data):6} bytes gzip")

        lines.append(f"// Asset: {filename} (Raw: {len(raw_data)} bytes, Gzip: {len(gz_data)} bytes)")
        lines.append(f"const size_t {var_name}_len = {len(gz_data)};")
        lines.append(f"const uint8_t {var_name}[] PROGMEM = {{")

        # Format hex bytes in rows of 16
        for i in range(0, len(gz_data), 16):
            chunk = gz_data[i:i+16]
            hex_str = ", ".join(f"0x{b:02X}" for b in chunk)
            comma = "," if i + 16 < len(gz_data) else ""
            lines.append(f"    {hex_str}{comma}")

        lines.append("};")
        lines.append("")

    lines.append("#endif // WEB_ASSETS_H")

    with open(output_header, 'w', encoding='utf-8') as f:
        f.write("\n".join(lines) + "\n")

    print(f"\nSuccessfully generated {output_header}")
    print(f"Total Raw: {total_raw} bytes -> Total Gzip in PROGMEM: {total_gz} bytes (~{total_gz / 1024:.1f} KB)\n")

if __name__ == '__main__':
    generate_header()
